 void Awake(){hud=GetComponent<RiftGameplayHUD>();player=hud.Design.Find("Player vitals") as RectTransform;foreach(Transform child in player)child.gameObject.SetActive(false);foreach(Transform child in hud.TargetPanel)child.gameObject.SetActive(false);Frame(player);Frame(hud.TargetPanel);
