 void Frame(RectTransform root){var old=root.GetComponent<RiftMapSurface>();if(old)old.enabled=false;var child=RiftHUDIntegratedBar.Rect(root,"Angular unit frame",0,0,1,Height);child.SetAsFirstSibling();var chrome=child.gameObject.AddComponent<RiftHUDChrome>();chrome.Cut=8;chrome.raycastTarget=false;}
