 static void Stretch(RectTransform r){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.pivot=new Vector2(.5f,.5f);r.offsetMin=r.offsetMax=Vector2.zero;r.localScale=Vector3.one;}
 RectTransform PortraitMask(Transform parent,string name){var r=RiftHUDIntegratedBar.Rect(parent,name,0,0,116,Height);var g=r.gameObject.AddComponent<RiftHUDChrome>();g.Cut=8;g.raycastTarget=true;r.gameObject.AddComponent<Mask>().showMaskGraphic=true;return r;}
 Text Label(Transform parent,string name,int size,TextAnchor alignment){var t=RiftHUDIntegratedBar.Rect(parent,name,0,0,1,1).gameObject.AddComponent<Text>();t.font=hud.Theme.BodyFont;t.fontSize=size;t.alignment=alignment;t.color=new Color(.94f,.91f,.98f);t.raycastTarget=false;return t;}
 static void Move(Text t,Transform p,float x,float y,float w,float h,int size,TextAnchor align){t.transform.SetParent(p,false);RiftHUDIntegratedBar.Place(t.rectTransform,x,y,w,h);t.gameObject.SetActive(true);t.fontSize=size;t.alignment=align;}
 static void Bar(RiftHUDGraphic fill,Transform parent,string name,float x,float y,float w,float h){var frame=parent.Find(name) as RectTransform;if(frame){RiftHUDIntegratedBar.Place(frame,x,y,w,h);frame.gameObject.SetActive(true);var g=frame.GetComponent<RiftHUDGraphic>();if(g){g.color=new Color(.035f,.027f,.05f);g.Bottom=new Color(.015f,.015f,.02f);g.Border=new Color(.44f,.32f,.57f);g.SetVerticesDirty();}}fill.transform.SetParent(parent,false);RiftHUDIntegratedBar.Place(fill.rectTransform,x+2,y+2,w-4,h-4);fill.gameObject.SetActive(true);}
 void LateUpdate(){LayoutDefaults();var p=ClientFrontend.ClientPlayerInstance;var combat=p?p.GetComponent<AbilityController>():null;playerLevel.text=combat?"Nv. "+combat.Level:"";bool visible=GetComponent<Canvas>().enabled;playerPortrait.enabled=visible;portrait.enabled=visible;if(!combat||!combat.Actor){playerPortrait.Show(null,null);portrait.Show(null,null);resourceRoot.gameObject.SetActive(false);targetResource.gameObject.SetActive(false);return;}playerPortrait.Show(combat.Actor.transform,null);var selected=hud.SelectedTarget;var npc=hud.SelectedNPC;var targetCombat=selected?AbilityController.For(selected):null;var nativeEnemy=selected?selected.GetComponent<MultiFPS.Gameplay.RiftEnemies.RiftEnemyAgent>():null;targetLevel.text=targetCombat?"Nv. "+targetCombat.Level:nativeEnemy?"Nv. "+nativeEnemy.Level:"";targetLevel.color=nativeEnemy&&nativeEnemy.Level>combat.Level?new Color(1,.32f,.24f):new Color(.85f,.8f,.94f);relation.text=selected?(selected==combat.Actor.Health?"VOS":selected.Team==combat.Actor.Health.Team?"ALIADO":"HOSTIL"):npc?"AMISTOSO":"";relation.color=selected&&selected!=combat.Actor.Health&&selected.Team!=combat.Actor.Health.Team?new Color(1,.26f,.25f):new Color(.34f,.94f,.61f);
  if(relationFrame.Border!=relation.color){relationFrame.Border=relation.color;relationFrame.SetVerticesDirty();}bool resource=targetCombat&&targetCombat.Prototype&&targetCombat.Class;resourceRoot.gameObject.SetActive(resource);targetResource.gameObject.SetActive(resource);if(resource){float ratio=Mathf.Clamp01(targetCombat.Resource/Mathf.Max(1,targetCombat.Class.MaximumResource));resourceFill.type=Image.Type.Simple;resourceFill.fillAmount=ratio;resourceFill.enabled=ratio>0;var fillRect=resourceFill.rectTransform;fillRect.anchorMin=Vector2.zero;fillRect.anchorMax=new Vector2(ratio,1);fillRect.offsetMin=fillRect.offsetMax=Vector2.zero;targetResource.text="Furia "+targetCombat.Resource.ToString("0")+" / "+targetCombat.Class.MaximumResource.ToString("0");}portrait.Show(selected?selected.transform:npc?npc.transform:null,null);
  bool cap=combat.Level>=combat.Progression.MaximumLevel;int xp=combat.Progression.InLevel(combat.Experience),required=combat.Progression.Required(combat.Level);hud.ExperienceLabel.text=cap?"NIVEL MÁXIMO":"XP "+xp+" / "+required+"  ·  "+(required>0?100f*xp/required:0).ToString("0")+"%";
